class FindSumPairs {
    private final int[] nums1,nums2;
    private final Map<Integer,Integer> frequency=new HashMap<>();
    public FindSumPairs(int[] nums1,int[] nums2){
        this.nums1=nums1;
        this.nums2=nums2;
        for(int value:nums2)frequency.merge(value,1,Integer::sum);
    }
    public void add(int index,int val){
        frequency.merge(nums2[index],-1,Integer::sum);
        nums2[index]+=val;
        frequency.merge(nums2[index],1,Integer::sum);
    }
    public int count(int tot){
        int answer=0;
        for(int value:nums1)answer+=frequency.getOrDefault(tot-value,0);
        return answer;
    }
}

code.kotlin:
class FindSumPairs(private val nums1:IntArray,private val nums2:IntArray){
    private val frequency=HashMap<Int,Int>();
    init{
        for(value in nums2)frequency[value]=(frequency[value]?:0)+1
    }
    fun add(index:Int,value:Int){
        frequency[nums2[index]]=(frequency[nums2[index]]?:0)-1;
        nums2[index]+=value;
        frequency[nums2[index]]=(frequency[nums2[index]]?:0)+1
    }
    fun count(total:Int):Int{
        var answer=0;
        for(value in nums1)answer+=frequency[total-value]?:0;
        return answer
    }
}

